DROP TABLE IF EXISTS `siakad_nilais`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `siakad_nilais` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `mahasiswa_id` bigint(20) unsigned NOT NULL,
  `mata_kuliah_id` bigint(20) unsigned NOT NULL,
  `semester` varchar(255) NOT NULL,
  `nilai_huruf` varchar(255) NOT NULL,
  `nilai_angka` decimal(5,2) NOT NULL,
  `bobot` decimal(5,2) NOT NULL,
  `sks` int(11) NOT NULL,
  `sumber_data` varchar(255) NOT NULL DEFAULT 'SIAKAD',
  `has_conflict` tinyint(1) NOT NULL DEFAULT 0,
  `conflict_details` text DEFAULT NULL,
  `imported_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `siakad_nilais_mahasiswa_id_foreign` (`mahasiswa_id`),
  KEY `siakad_nilais_mata_kuliah_id_foreign` (`mata_kuliah_id`),
  CONSTRAINT `siakad_nilais_mahasiswa_id_foreign` FOREIGN KEY (`mahasiswa_id`) REFERENCES `mahasiswas` (`id`) ON DELETE CASCADE,
  CONSTRAINT `siakad_nilais_mata_kuliah_id_foreign` FOREIGN KEY (`mata_kuliah_id`) REFERENCES `siakad_mata_kuliahs` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=9380 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
