--
-- Table structure for table `wisudawans`
--

DROP TABLE IF EXISTS `wisudawans`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `wisudawans` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `mahasiswa_id` bigint(20) unsigned DEFAULT NULL,
  `nim` varchar(255) NOT NULL,
  `nama` varchar(255) DEFAULT NULL,
  `nomor_pendaftaran_wisuda` varchar(255) DEFAULT NULL,
  `periode_wisuda` varchar(255) NOT NULL,
  `tanggal_wisuda` date DEFAULT NULL,
  `fakultas` varchar(255) DEFAULT NULL,
  `program_studi` varchar(255) DEFAULT NULL,
  `no_sk` varchar(255) DEFAULT NULL,
  `tanggal_sk` date DEFAULT NULL,
  `no_ijazah` varchar(255) DEFAULT NULL,
  `tanggal_ijazah` date DEFAULT NULL,
  `ipk` decimal(4,2) DEFAULT NULL,
  `total_sks` smallint(5) unsigned DEFAULT NULL,
  `lama_studi` tinyint(3) unsigned DEFAULT NULL,
  `semester_lulus` varchar(30) DEFAULT NULL,
  `gelar` varchar(50) DEFAULT NULL,
  `gelar_full` varchar(150) DEFAULT NULL,
  `judul_skripsi` varchar(255) DEFAULT NULL,
  `predikat_kelulusan` varchar(255) DEFAULT NULL,
  `is_eligible` tinyint(1) NOT NULL DEFAULT 1,
  `status_validasi` varchar(255) NOT NULL DEFAULT 'Draft',
  `sumber_data` varchar(255) NOT NULL DEFAULT 'WISUDAWAN',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
